scripts.protoc:
node -e "require('fs').mkdirSync('src/clients/generated', { recursive: true })" && grpc_tools_node_protoc --ts_out=target=web,unary_rpc_promise=true,no_namespace:./src/clients/generated -I=../Protos catalog.proto order.proto payment.proto && node -e "const fs=require('fs');['catalog.ts','order.ts','payment.ts'].forEach(f=>{const p='src/clients/generated/'+f;if(fs.existsSync(p)){let c=fs.readFileSync(p,'utf8').replace(//\*[\s\S]*?\*//g,'').replace(///.*/g,'');fs.writeFileSync(p,c);}});fs.writeFileSync('src/clients/generated/index.ts','export * from './catalog';
export * from './order';
export * from './payment';
');"
